-- BaneySpaces key bindings for Omarchy/Hyprland. Generated by `baneyspaces keys --hypr-lua`
-- from spec/keys.json; do not edit by hand. Loaded by hyprland.lua after Omarchy's defaults.

-- Omarchy's own bindings for these keys, replaced below (install.sh backs up what it changes).
hl.unbind("SUPER + code:10")
hl.unbind("SUPER + code:11")
hl.unbind("SUPER + code:12")
hl.unbind("SUPER + code:13")
hl.unbind("SUPER + code:14")
hl.unbind("SUPER + code:15")
